std::map<int, int> scores{{4, 12}};
auto it = scores.find(9);
if (it != scores.end()) {
  std::cout << it->second;
}
// Ключ 9 не добавлен; size() == 1.

std::map<int, int> limits;
auto result = limits.insert_or_assign(7, 20);
// Ключа 7 не было: вставлена пара {7, 20}.
// result.first — итератор на эту пару; result.first->second == 20.
// result.second == true: произошла вставка, а не обновление.

std::string word = "planet";
auto part = word.substr(2, 3);
// part == "ane"; исходная word не изменена.
// Для pos > word.size() описание конструктора, на который ссылается substr,
// требует std::out_of_range, а не пустую строку.
